 if($action==='mapping'){$tag=(string)$_POST['tag'];$category=(string)$_POST['category'];if(!isset(activityTypes()[$category]))throw new InvalidArgumentException('קטגוריה לא תקינה');$q=$d->prepare("SELECT count(*) FROM provider_records WHERE stream='tags' AND id=?");$q->execute([$tag]);if(!$q->fetchColumn())throw new InvalidArgumentException('תג לא נמצא');$q=$d->prepare('INSERT INTO tag_mappings VALUES(?,?,1,?) ON CONFLICT(tag_id) DO UPDATE SET category_id=excluded.category_id,reviewed=1,updated_at=excluded.updated_at');$q->execute([$tag,$category,time()]);$result=['state'=>'mapping_saved'];}
