<?php require ROOT.'/views/admin-practical.php';?><section class="form-panel" id="content"><h2>רשומות תוכן</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="new_export"><label>סוג <select name="kind"><option value="article">מדריך</option><option value="place">מקום</option><option value="experience">חוויה</option><option value="destination">יעד</option><option value="category">קטגוריה</option></select></label><label>מספר טיוטות <input type="number" name="count" min="1" max="10" value="1"></label><button class="button secondary">תבנית חדשה להורדה</button></form><div class="table-scroll"><table><tr><th>מזהה / סוג</th><th>כותרת</th><th>גרסה</th><th>שפות</th><th>פרסום ושחזור</th></tr><?php if($d)foreach($d->query('SELECT * FROM editorial_records ORDER BY kind,id') as $r):$doc=json_decode($r['document'],true);?><tr><td><?=e($r['id'].' / '.$r['kind'])?><form method="post"><?=csrf()?><input type="hidden" name="action" value="export"><input type="hidden" name="ids" value="<?=e($r['id'])?>"><button class="button secondary">ייצוא הפריט</button></form></td><td><?=e($doc['editorial']['translations']['he']['title']??'טיוטה ריקה')?></td><td><?=$r['revision']?></td><td><?php foreach($doc['editorial']['translations']??[] as $l=>$tr)echo e($l.': '.($tr['translation_status']??'draft')).'<br>';?></td><td><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=e($r['id'])?>"><input type="hidden" name="revision" value="<?=$r['revision']?>"><label><input type="checkbox" name="reviewed" value="1"> בדקתי את התוכן, התרגומים והתמונה</label><button name="action" value="publish">פרסום נפרד</button><button name="action" value="archive">ארכוב</button><label>גרסה לשחזור<input name="target" type="number" min="1" max="<?=$r['revision']?>" value="<?=max(1,$r['revision']-1)?>"></label><button name="action" value="restore">שחזור לטיוטה</button></form></td></tr><?php endforeach?></table></div></section>
